mapper.select:
select T7.PORTFOLIO_ID,T7.SEC_ACCT_ID,SUM(T7.AMT) PRIN_AMT from( select T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID,SUM((CASE WHEN T1.PS =#{pin} THEN T2.AMT WHEN #{pout} THEN T2.AMT*-1 END)*NULLIF(T6.SCALE,0)) AMT from TRD_STASEC_FLOW T1 INNER JOIN TRD_STASEC_FLOW_DETAIL T2 ON T1.SEQNO = T2.SEQNO left join (select T3.FINPROD_ID,T3.SCALE from FIN_STDSEC_CONVERSE_RADIO T3 INNER JOIN (select T4.FINPROD_ID,MAX(T4.VDATE) VDATE from FIN_STDSEC_CONVERSE_RADIO T4
T4.VDATE <= #{sysDate}
group by T4.FINPROD_ID) T5 ON T3.FINPROD_ID = T5.FINPROD_ID
T3.VDATE = T5.VDATE
) T6 ON T6.FINPROD_ID = T2.FINPROD_ID
T1.PORTFOLIO_ID = #{portfolioId} AND T1.SEC_ACCT_ID = #{manageId}
group by T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID ) T7 group by T7.PORTFOLIO_ID,T7.SEC_ACCT_ID
